package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact four API67 serialization/parser tail cases admitted in Wave41.
func TestRunJSONSObjectTailContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeScalarJsonTailObserve67.cls"), "@IsTest private class GladeScalarJsonTailObserve67 {\nprivate static void record(List<Object> rows,String name,Object value){rows.add(new Map<String,Object>{'n'=>name,'value'=>value});}\nprivate static void failure(List<Object> rows,String name,Exception e){rows.add(new Map<String,Object>{'n'=>name,'type'=>e.getTypeName(),'message'=>e.getMessage()});}\nprivate static void finish(List<Object> rows,Integer expected){System.assertEquals(expected,rows.size(),'Every original operation observation retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Owned JSON tail observation exceeds bound');}\n@IsTest static void mapSerializationSettings(){\nList<Object> rows=new List<Object>();\nMap<String,Object> serial = new Map<String,Object>();\nserial.put('name', 'Acme');\nserial.put('missing', null);\nList<Object> serialItems = new List<Object>();\nserialItems.add(1);\nserialItems.add(null);\nserial.put('items', serialItems);\n\ntry{record(rows,'compactTrue',JSON.serialize(serial,true));}catch(Exception e){failure(rows,'compactTrue',e);}\ntry{record(rows,'compactFalse',JSON.serialize(serial,false));}catch(Exception e){failure(rows,'compactFalse',e);}\ntry{record(rows,'prettyTrue',JSON.serializePretty(serial,true));}catch(Exception e){failure(rows,'prettyTrue',e);}\ntry{record(rows,'prettyFalse',JSON.serializePretty(serial,false));}catch(Exception e){failure(rows,'prettyFalse',e);}\nfinish(rows,4);\nassertExactRows(rows,new List<Object>{new Map<String,Object>{'n'=>'compactTrue','value'=>'{\"items\":[1,null],\"missing\":null,\"name\":\"Acme\"}'},new Map<String,Object>{'n'=>'compactFalse','value'=>'{\"items\":[1,null],\"missing\":null,\"name\":\"Acme\"}'},new Map<String,Object>{'n'=>'prettyTrue','value'=>'{\\n  \"items\" : [ 1, null ],\\n  \"missing\" : null,\\n  \"name\" : \"Acme\"\\n}'},new Map<String,Object>{'n'=>'prettyFalse','value'=>'{\\n  \"items\" : [ 1, null ],\\n  \"missing\" : null,\\n  \"name\" : \"Acme\"\\n}'}});\n}\n@IsTest static void accountSerializationSettings(){\nList<Object> rows=new List<Object>();\nAccount account = new Account(Name = 'NoNull', Phone = null);\ntry{record(rows,'compactTrue',JSON.serialize(account,true));}catch(Exception e){failure(rows,'compactTrue',e);}\ntry{record(rows,'compactFalse',JSON.serialize(account,false));}catch(Exception e){failure(rows,'compactFalse',e);}\ntry{record(rows,'prettyTrue',JSON.serializePretty(account,true));}catch(Exception e){failure(rows,'prettyTrue',e);}\ntry{record(rows,'prettyFalse',JSON.serializePretty(account,false));}catch(Exception e){failure(rows,'prettyFalse',e);}\nfinish(rows,4);\nassertExactRows(rows,new List<Object>{new Map<String,Object>{'n'=>'compactTrue','value'=>'{\"attributes\":{\"type\":\"Account\"},\"Name\":\"NoNull\",\"Phone\":null}'},new Map<String,Object>{'n'=>'compactFalse','value'=>'{\"attributes\":{\"type\":\"Account\"},\"Name\":\"NoNull\",\"Phone\":null}'},new Map<String,Object>{'n'=>'prettyTrue','value'=>'{\\n  \"attributes\" : {\\n    \"type\" : \"Account\"\\n  },\\n  \"Name\" : \"NoNull\",\\n  \"Phone\" : null\\n}'},new Map<String,Object>{'n'=>'prettyFalse','value'=>'{\\n  \"attributes\" : {\\n    \"type\" : \"Account\"\\n  },\\n  \"Name\" : \"NoNull\",\\n  \"Phone\" : null\\n}'}});\n}\n@IsTest static void parserThroughOriginalId(){\nList<Object> rows=new List<Object>();\nJSONParser parser = JSON.createParser('[{\"id\":\"001B000001DVM9t\",\"blob\":\"YWJj\"},false]');\n\ntry{record(rows,'nextArray',parser.nextToken());}catch(Exception e){failure(rows,'nextArray',e);}\ntry{record(rows,'nextObject',parser.nextToken());}catch(Exception e){failure(rows,'nextObject',e);}\ntry{record(rows,'nextIdField',parser.nextToken());}catch(Exception e){failure(rows,'nextIdField',e);}\ntry{record(rows,'idFieldName',parser.getCurrentName());}catch(Exception e){failure(rows,'idFieldName',e);}\ntry{record(rows,'nextIdValue',parser.nextValue());}catch(Exception e){failure(rows,'nextIdValue',e);}\ntry{record(rows,'idText',parser.getIdValue().toString());}catch(Exception e){failure(rows,'idText',e);}\nfinish(rows,6);\nassertExactRows(rows,new List<Object>{new Map<String,Object>{'n'=>'nextArray','value'=>JSONToken.START_ARRAY},new Map<String,Object>{'n'=>'nextObject','value'=>JSONToken.START_OBJECT},new Map<String,Object>{'n'=>'nextIdField','value'=>JSONToken.FIELD_NAME},new Map<String,Object>{'n'=>'idFieldName','value'=>'id'},new Map<String,Object>{'n'=>'nextIdValue','value'=>JSONToken.VALUE_STRING},new Map<String,Object>{'n'=>'idText','value'=>'001B000001DVM9tIAH'}});\n}\n@IsTest static void parserAfterOriginalId(){\nList<Object> rows=new List<Object>();\nJSONParser parser = JSON.createParser('[{\"id\":\"001B000001DVM9t\",\"blob\":\"YWJj\"},false]');\n\nparser.nextToken();\nparser.nextToken();\nparser.nextToken();\nparser.getCurrentName();\nparser.nextValue();\nparser.getIdValue().toString();\ntry{record(rows,'nextBlobField',parser.nextToken());}catch(Exception e){failure(rows,'nextBlobField',e);}\ntry{record(rows,'blobFieldName',parser.getCurrentName());}catch(Exception e){failure(rows,'blobFieldName',e);}\ntry{record(rows,'nextBlobValue',parser.nextValue());}catch(Exception e){failure(rows,'nextBlobValue',e);}\ntry{record(rows,'blobText',parser.getBlobValue().toString());}catch(Exception e){failure(rows,'blobText',e);}\ntry{record(rows,'endObject',parser.nextToken());}catch(Exception e){failure(rows,'endObject',e);}\ntry{record(rows,'nextFalse',parser.nextToken());}catch(Exception e){failure(rows,'nextFalse',e);}\ntry{record(rows,'booleanValue',parser.getBooleanValue());}catch(Exception e){failure(rows,'booleanValue',e);}\ntry{record(rows,'endArray',parser.nextToken());}catch(Exception e){failure(rows,'endArray',e);}\ntry{record(rows,'afterEnd',parser.nextToken());}catch(Exception e){failure(rows,'afterEnd',e);}\ntry{record(rows,'currentToken',parser.getCurrentToken());}catch(Exception e){failure(rows,'currentToken',e);}\ntry{record(rows,'currentName',parser.getCurrentName());}catch(Exception e){failure(rows,'currentName',e);}\ntry{record(rows,'tokenString',JSONToken.START_OBJECT.toString());}catch(Exception e){failure(rows,'tokenString',e);}\ntry{record(rows,'tokenEquality',JSONToken.VALUE_NUMBER_FLOAT == JSONToken.VALUE_NUMBER_FLOAT);}catch(Exception e){failure(rows,'tokenEquality',e);}\nfinish(rows,13);\nassertExactRows(rows,new List<Object>{new Map<String,Object>{'n'=>'nextBlobField','value'=>JSONToken.FIELD_NAME},new Map<String,Object>{'n'=>'blobFieldName','value'=>'blob'},new Map<String,Object>{'n'=>'nextBlobValue','value'=>JSONToken.VALUE_STRING},new Map<String,Object>{'n'=>'blobText','value'=>'abc'},new Map<String,Object>{'n'=>'endObject','value'=>JSONToken.END_OBJECT},new Map<String,Object>{'n'=>'nextFalse','value'=>JSONToken.VALUE_FALSE},new Map<String,Object>{'n'=>'booleanValue','value'=>false},new Map<String,Object>{'n'=>'endArray','value'=>JSONToken.END_ARRAY},new Map<String,Object>{'n'=>'afterEnd','value'=>null},new Map<String,Object>{'n'=>'currentToken','value'=>null},new Map<String,Object>{'n'=>'currentName','value'=>null},new Map<String,Object>{'n'=>'tokenString','value'=>'START_OBJECT'},new Map<String,Object>{'n'=>'tokenEquality','value'=>true}});\n}\nprivate static void assertExactRows(List<Object> rows,List<Object> expectedRows){\nSystem.assertEquals(expectedRows.size(),rows.size(),'Exact observed row population');\nfor(Integer i=0;i<expectedRows.size();i++){\nMap<String,Object> expectedRow=(Map<String,Object>)expectedRows[i];\nMap<String,Object> actualRow=(Map<String,Object>)rows[i];\nSystem.assertEquals(expectedRow.keySet(),actualRow.keySet(),'Exact row fields at '+i);\nSystem.assertEquals(expectedRow.get('n'),actualRow.get('n'),'Operation order at '+i);\nSystem.assertEquals(expectedRow.get('value'),actualRow.get('value'),'Observed value for '+expectedRow.get('n'));\n}\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeScalarJsonTailObserve67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 || got.Skipped != 0 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact JSON tail contracts failed: %s", data)
	}
}
